// Configuración del flujo A (actualizar biblioteca con Claude).
// Pega el link de tu Google Sheet (la que creaste importando prompts/banners.csv).
return [{
  json: {
    sheet_url: 'PEGA_AQUI_EL_LINK_DE_TU_GOOGLE_SHEET',
    claude_model: 'claude-opus-5-5',
    claude_effort: 'medium',
  },
}];

// Lee window.OK_CONFIG de revoimport.com/config.js y arma la ficha de cada producto.
// La huella cambia cuando cambian nombre, precios, precio anterior, colores, contenido o fotos.
const SITE = 'https://revoimport.com';
const raw = $input.first().json.data;

function parseConfig(text) {
  const start = text.indexOf('window.OK_CONFIG');
  const open = text.indexOf('{', start);
  if (start < 0 || open < 0) throw new Error('No se encontró window.OK_CONFIG en config.js');
  let depth = 0;
  let quote = '';
  let esc = false;
  for (let i = open; i < text.length; i++) {
    const c = text[i];
    if (quote) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === quote) quote = '';
      continue;
    }
    if (c === '"' || c === "'") quote = c;
    else if (c === '{') depth++;
    else if (c === '}' && --depth === 0) return JSON.parse(text.slice(open, i + 1));
  }
  throw new Error('config.js incompleto');
}

const abs = (p) => (p ? (p.startsWith('http') ? p : `${SITE}/${p.replace(/^\//, '')}`) : null);
const soles = (n) => `S/ ${Number(n).toLocaleString('en-US')}`;
const hash = (s) => {
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0;
  return h.toString(16).padStart(8, '0');
};
const uniq = (a) => [...new Set(a.filter((x) => x !== null && x !== undefined && x !== ''))];

const cfg = parseConfig(raw);
const promoIphone = (cfg.giftPromotions || []).find((g) => g.id === 'iphone-four');
const global = {
  marca: cfg.brand,
  whatsapp: `+${cfg.country} ${cfg.whatsapp}`,
  pagos: cfg.payments || [],
  envios: cfg.shipping || {},
  regalos_iphone: promoIphone && promoIphone.enabled ? promoIphone.gifts.map((g) => g.name) : [],
  nota_regalos: promoIphone ? promoIphone.note : '',
};

return (cfg.products || []).map((p) => {
  const variants = p.variants || [];
  const precios = uniq(variants.map((v) => v.price)).sort((a, b) => a - b);
  const imgs = [];
  for (const arr of Object.values(p.galleries || {})) imgs.push(...arr.slice(0, 3));
  for (const k of ['cover', 'image']) if (p[k]) imgs.push(p[k]);
  for (const g of p.galleryViews || []) if (g && g.src) imgs.push(g.src);
  const ficha = {
    id: p.id,
    nombre: p.name,
    categoria: p.category,
    precio: precios.length > 1 ? `Desde ${soles(precios[0])}` : precios.length ? soles(precios[0]) : '',
    precio_antes: p.previousPrice ? soles(p.previousPrice) : null,
    precios,
    capacidades: uniq(variants.map((v) => v.capacity)),
    sim: uniq(variants.map((v) => v.sim)),
    colores: (p.colors || []).map((c) => c.name),
    tamano: p.size || null,
    descripcion: p.description || '',
    incluye: p.includes || [],
    etiqueta: p.conditionBadge || p.sourceBadge || p.label || p.tag || null,
    garantia: p.warranty || null,
    original: p.genuine === undefined ? null : p.genuine,
    nota_autenticidad: p.authenticityNote || null,
    envio: p.deliveryOffer || null,
    disponibilidad: uniq(variants.map((v) => v.availability)),
    link: `${SITE}/p/${p.id}/`,
    imagenes: uniq(imgs.map(abs)),
    global,
  };
  ficha.huella = hash(JSON.stringify({
    n: ficha.nombre, p: ficha.precios, a: ficha.precio_antes, c: ficha.colores, i: ficha.incluye, im: ficha.imagenes,
  }));
  return { json: ficha };
});

// Convierte la respuesta de Claude en filas de la hoja (estado "pendiente" para que las apruebes).
const prev = $('A · Detectar cambios').all().map((i) => i.json);
const now = new Date().toISOString();
const NOMBRES = {
  "T1": "Diagrama de partes (callouts numerados)",
  "T2": "Flat lay con 3 llamadas",
  "T3": "Ficha técnica",
  "T4": "Oferta + plantilla de reseña",
  "T5": "Knolling: problema → solución"
};
const VACIO = {
  request_master: '', status_url_master: '', url_master: '', qa_resultado: '', qa_problemas: '',
  request_1x1: '', status_url_1x1: '', url_1x1: '', request_9x16: '', status_url_9x16: '', url_9x16: '',
};

const out = [];
$input.all().forEach((item, idx) => {
  const ctx = prev[idx];
  const r = item.json;
  let data = null;
  let error = '';
  if (r.error) error = `Error de la API de Claude: ${JSON.stringify(r.error).slice(0, 300)}`;
  else if (r.stop_reason === 'refusal') error = 'Claude rechazó la solicitud.';
  else if (r.stop_reason === 'max_tokens') error = 'La respuesta de Claude quedó cortada (max_tokens).';
  else {
    try {
      data = JSON.parse((r.content || []).filter((b) => b.type === 'text').map((b) => b.text).join(''));
    } catch (e) {
      error = 'La respuesta de Claude no es JSON válido.';
    }
  }
  if (!data) {
    for (const a of ctx.actuales) {
      out.push({ json: { id: a.id, estado: 'error_claude', qa_problemas: error, actualizado: now } });
    }
    return;
  }
  const f = ctx.ficha;
  const meta = data.meta || {};
  for (const fila of data.filas || []) {
    const id = `${f.id}__${fila.plantilla}`;
    const anterior = ctx.actuales.find((a) => a.id === id);
    out.push({
      json: {
        id,
        producto_id: f.id,
        producto: f.nombre,
        categoria: f.categoria,
        plantilla: fila.plantilla,
        plantilla_nombre: NOMBRES[fila.plantilla] || fila.plantilla,
        precio: f.precio,
        link: f.link,
        refs: (fila.refs || []).join(' | '),
        textos_imagen: JSON.stringify(fila.textos_imagen || []),
        prompt_master_3x4: fila.prompt_master_3x4,
        prompt_1x1: fila.prompt_1x1,
        prompt_9x16: fila.prompt_9x16,
        meta_texto_1: (meta.textos || [])[0] || '',
        meta_texto_2: (meta.textos || [])[1] || '',
        meta_texto_3: (meta.textos || [])[2] || '',
        meta_titulo_1: (meta.titulos || [])[0] || '',
        meta_titulo_2: (meta.titulos || [])[1] || '',
        meta_titulo_3: (meta.titulos || [])[2] || '',
        meta_descripcion: meta.descripcion || '',
        meta_boton: 'Enviar mensaje',
        requiere_resena_real: fila.plantilla === 'T4' ? 'sí' : 'no',
        huella: f.huella,
        estado: 'pendiente',
        version: (Number(anterior && anterior.version) || 0) + 1,
        ...VACIO,
        actualizado: now,
        notas_claude: data.notas || '',
      },
    });
  }
});
return out;

// Configuración del flujo B (generar en Higgsfield las filas con estado "aprobado").
// max_por_corrida limita cuántos banners se envían por clic (cada uno = 1 master + 2 formatos).
return [{
  json: {
    sheet_url: 'PEGA_AQUI_EL_LINK_DE_TU_GOOGLE_SHEET',
    max_por_corrida: 2,
    resolucion: '2k',
    calidad: 'high',
  },
}];

// Arma la solicitud a Higgsfield (Marketing Studio Image 2.5 Flare) para el master 3:4 de cada fila aprobada.
const cfg = $('B · Config').first().json;
const filas = $input.all().map((i) => i.json).filter((r) => r.id && r.estado === 'aprobado');
const lote = Date.now();
return filas.slice(0, cfg.max_por_corrida).map((r) => ({
  json: {
    id: r.id,
    // Misma clave en reintentos de esta corrida; nueva clave si vuelves a aprobar la fila más tarde.
    idempotency_key: `${r.id}-v${r.version || 1}-master-${lote}`,
    hf_body: {
      prompt: r.prompt_master_3x4,
      image_urls: String(r.refs || '').split('|').map((u) => u.trim()).filter(Boolean).slice(0, 16),
      aspect_ratio: '3:4',
      resolution: cfg.resolucion,
      quality: cfg.calidad,
      enhance_prompt: false,
    },
  },
}));

// Guarda en la hoja el request_id que devolvió Higgsfield.
const prev = $('B · Preparar solicitudes').all().map((i) => i.json);
const now = new Date().toISOString();
return $input.all().map((item, i) => {
  const r = item.json;
  const fila = prev[i];
  if (r.error || !r.request_id) {
    return {
      json: {
        id: fila.id,
        estado: 'error',
        qa_problemas: `Higgsfield no aceptó el master: ${JSON.stringify(r.error || r).slice(0, 300)}`,
        actualizado: now,
      },
    };
  }
  return {
    json: {
      id: fila.id,
      estado: 'generando_master',
      request_master: r.request_id,
      status_url_master: r.status_url,
      url_master: '', qa_resultado: '', qa_problemas: '',
      request_1x1: '', status_url_1x1: '', url_1x1: '', request_9x16: '', status_url_9x16: '', url_9x16: '',
      actualizado: now,
    },
  };
});

// Configuración del flujo C (revisar trabajos en curso, QA con GPT-6 Astra y formatos 1:1 / 9:16).
// Si tu cuenta de OpenAI aún no tiene acceso a gpt-6-astra, pon aquí otro modelo de OpenAI con visión que sí tengas.
return [{
  json: {
    sheet_url: 'PEGA_AQUI_EL_LINK_DE_TU_GOOGLE_SHEET',
    openai_model: 'gpt-6-astra',
    resolucion: '2k',
    calidad: 'high',
  },
}];

// Toma las filas con trabajos en curso: masters por revisar y formatos por terminar.
const out = [];
for (const r of $input.all().map((i) => i.json)) {
  if (!r.id) continue;
  if (r.estado === 'generando_master' && r.status_url_master) {
    out.push({ json: { tipo: 'master', id: r.id, status_url: r.status_url_master, fila: r } });
  }
  if (r.estado === 'generando_formatos') {
    for (const ratio of ['1x1', '9x16']) {
      if (r[`status_url_${ratio}`]) {
        out.push({ json: { tipo: 'formato', ratio, id: r.id, status_url: r[`status_url_${ratio}`], fila: r } });
      }
    }
  }
}
return out;

// Lee el estado del master y, si terminó, prepara la revisión de calidad con GPT-6 Astra.
const prev = $('C · ¿Es master?').all(0).map((i) => i.json);
const cfg = $('C · Config').first().json;
const QA_PROMPT = "Eres el control de calidad de anuncios de REVO Store (Perú). La primera imagen es un banner generado para Meta Ads del producto \"{PRODUCTO}\". Las imágenes siguientes son fotos reales del producto tomadas de revoimport.com.\n\nRevisa el banner y responde con el esquema JSON:\n1. texto_correcto: cada uno de estos textos aparece en el banner exactamente así, con sus tildes y sin faltas, y no hay palabras extra inventadas:\n{TEXTOS}\n2. sin_logos: no aparece el logo de Apple, la palabra \"AirPods\" ni ningún otro logo o marca de terceros en equipos, cajas, cases o pantallas.\n3. producto_fiel: el producto coincide con las fotos de referencia (forma, color, número de cámaras, conectores) y no tiene accesorios, botones o puertos inventados.\n4. layout_ok: nada importante está cortado por los bordes, el texto se lee a tamaño de celular y no tapa el producto; no hay personas, manos, marcas de agua ni códigos QR.\n\naprobado es true solo si los cuatro puntos se cumplen. En problemas, describe cada defecto en una frase corta en español, diciendo dónde está (por ejemplo: \"El precio dice S/ 4,60 en vez de S/ 4,600, abajo al centro\"). Si todo está bien, deja problemas vacío.\n";
const QA_SCHEMA = {
  "type": "object",
  "additionalProperties": false,
  "required": [
    "aprobado",
    "texto_correcto",
    "sin_logos",
    "producto_fiel",
    "layout_ok",
    "problemas"
  ],
  "properties": {
    "aprobado": {
      "type": "boolean"
    },
    "texto_correcto": {
      "type": "boolean"
    },
    "sin_logos": {
      "type": "boolean"
    },
    "producto_fiel": {
      "type": "boolean"
    },
    "layout_ok": {
      "type": "boolean"
    },
    "problemas": {
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  }
};

return $input.all().map((item, i) => {
  const s = item.json;
  const r = prev[i].fila;
  const status = s.status || (s.error ? 'error_consulta' : '');
  const fase = status === 'completed' ? 'completado' : ['failed', 'nsfw', 'canceled'].includes(status) ? 'fallido' : 'en_proceso';
  const url = (s.images && s.images[0] && s.images[0].url) || '';
  let textos = [];
  try { textos = JSON.parse(r.textos_imagen || '[]'); } catch (e) { textos = []; }
  const refs = String(r.refs || '').split('|').map((u) => u.trim()).filter(Boolean).slice(0, 3);
  const qa_body = fase !== 'completado' ? null : {
    model: cfg.openai_model,
    input: [{
      role: 'user',
      content: [
        {
          type: 'input_text',
          text: QA_PROMPT.replace('{PRODUCTO}', r.producto).replace('{TEXTOS}', textos.map((t) => `- "${t}"`).join('\n')),
        },
        { type: 'input_image', image_url: url },
        ...refs.map((u) => ({ type: 'input_image', image_url: u })),
      ],
    }],
    text: { format: { type: 'json_schema', name: 'qa_banner', strict: true, schema: QA_SCHEMA } },
  };
  return { json: { id: r.id, fila: r, fase, status, url_master: url, qa_body } };
});

// Interpreta el veredicto de GPT-6 Astra.
const prev = $('C · ¿Master listo?').all(0).map((i) => i.json);
return $input.all().map((item, i) => {
  const r = item.json;
  let text = r.output_text || '';
  if (!text && Array.isArray(r.output)) {
    for (const o of r.output) {
      if (o.type !== 'message') continue;
      for (const c of o.content || []) if (c.type === 'output_text') text += c.text;
    }
  }
  let qa = null;
  try { qa = JSON.parse(text); } catch (e) { qa = null; }
  const problemas = qa
    ? (qa.problemas || []).join(' | ')
    : `QA sin respuesta válida${r.error ? `: ${JSON.stringify(r.error).slice(0, 200)}` : ''}`;
  return { json: { ...prev[i], qa_aprobado: !!(qa && qa.aprobado), qa_problemas: problemas } };
});

// Con el master aprobado, pide a Higgsfield las versiones 1:1 (Feed) y 9:16 (Stories y Reels).
const cfg = $('C · Config').first().json;
const out = [];
for (const item of $input.all()) {
  const p = item.json;
  const r = p.fila;
  for (const [ratio, aspect, prompt] of [['1x1', '1:1', r.prompt_1x1], ['9x16', '9:16', r.prompt_9x16]]) {
    out.push({
      json: {
        id: r.id,
        ratio,
        url_master: p.url_master,
        qa_problemas: p.qa_problemas,
        idempotency_key: `${r.id}-v${r.version || 1}-${ratio}-${r.request_master}`,
        hf_body: {
          prompt,
          image_urls: [p.url_master],
          aspect_ratio: aspect,
          resolution: cfg.resolucion,
          quality: cfg.calidad,
          enhance_prompt: false,
        },
      },
    });
  }
}
return out;

// Agrupa por fila los request_id de los dos formatos.
const prev = $('C · Preparar formatos').all().map((i) => i.json);
const now = new Date().toISOString();
const porFila = {};
$input.all().forEach((item, i) => {
  const s = item.json;
  const p = prev[i];
  const row = porFila[p.id] || (porFila[p.id] = {
    id: p.id, estado: 'generando_formatos', url_master: p.url_master,
    qa_resultado: 'aprobado', qa_problemas: p.qa_problemas || '', actualizado: now,
  });
  if (s.error || !s.request_id) {
    row.estado = 'error_formatos';
    row.qa_problemas = `${row.qa_problemas} | Higgsfield no aceptó el formato ${p.ratio}`.replace(/^ \| /, '');
    return;
  }
  row[`request_${p.ratio}`] = s.request_id;
  row[`status_url_${p.ratio}`] = s.status_url;
});
return Object.values(porFila).map((json) => ({ json }));

// El QA encontró problemas: queda para que lo revises (vuelve a poner "aprobado" para regenerar).
const now = new Date().toISOString();
return $input.all().map((item) => ({
  json: {
    id: item.json.id,
    estado: 'revisar',
    url_master: item.json.url_master,
    qa_resultado: 'observado',
    qa_problemas: item.json.qa_problemas,
    actualizado: now,
  },
}));

// Higgsfield terminó el master con error.
const now = new Date().toISOString();
return $input.all().map((item) => ({
  json: {
    id: item.json.id,
    estado: 'error',
    qa_problemas: `Higgsfield terminó el master con estado "${item.json.status}"`,
    actualizado: now,
  },
}));

// Cuando las dos versiones terminan, guarda sus links y marca la fila como lista.
const prev = $('C · ¿Es master?').all(1).map((i) => i.json);
const now = new Date().toISOString();
const FIN_MAL = ['failed', 'nsfw', 'canceled'];
const grupos = {};
$input.all().forEach((item, i) => {
  const s = item.json;
  const p = prev[i];
  const g = grupos[p.id] || (grupos[p.id] = { fila: p.fila, res: {} });
  g.res[p.ratio] = {
    status: s.status || (s.error ? 'error_consulta' : ''),
    url: (s.images && s.images[0] && s.images[0].url) || '',
  };
});
const out = [];
for (const [id, g] of Object.entries(grupos)) {
  const estados = Object.values(g.res).map((x) => x.status);
  if (estados.some((x) => FIN_MAL.includes(x))) {
    out.push({ json: { id, estado: 'error_formatos', qa_problemas: `Formato con estado ${estados.join('/')}`, actualizado: now } });
  } else if (estados.length === 2 && estados.every((x) => x === 'completed')) {
    out.push({
      json: {
        id,
        estado: g.fila.requiere_resena_real === 'sí' ? 'listo_falta_resena' : 'listo',
        url_1x1: g.res['1x1'].url,
        url_9x16: g.res['9x16'].url,
        actualizado: now,
      },
    });
  }
}
return out;
